	/** 
	 * updating a RecordsRepository.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a RecordsRepository." );

		StringBuilder msg = new StringBuilder( "Failed to update a RecordsRepository : " );        
		RecordsRepository entity = read();
		UpdateRecordsRepositoryCommand command = generateUpdateCommand();
		command.setRecordsRepositoryId(entity.getRecordsRepositoryId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created RecordsRepository." );

			// for use later on...
			recordsRepositoryId = entity.getRecordsRepositoryId();

			RecordsRepositoryService proxy = RecordsRepositoryService.getRecordsRepositoryInstance();  

			proxy.updateRecordsRepository( command ).get();

			LOGGER.info( "-- Successfully saved RecordsRepository - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + recordsRepositoryId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a RecordsRepository.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created RecordsRepository." );

		RecordsRepository entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read RecordsRepository with id " + recordsRepositoryId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read RecordsRepository with id " + recordsRepositoryId );

			throw e;
		}

		try{
			RecordsRepositoryService.getRecordsRepositoryInstance().delete( new DeleteRecordsRepositoryCommand( entity.getRecordsRepositoryId() ) ).get();
			LOGGER.info( "-- Successfully deleted RecordsRepository with id " + recordsRepositoryId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete RecordsRepository with id " + recordsRepositoryId );

			throw e;
		}
	}

